sys_script_include.script:
var AttachmentBinaryISOConverter = Class.create();
AttachmentBinaryISOConverter.prototype = {
    initialize: function() {
    },
	convertToISO: function(grAttachment) {
        var gsa = new GlideSysAttachment();
        var binData = gsa.getBytes(grAttachment); 
        return new Packages.java.lang.String(binData, "ISO-8859-1");
    },
    type: 'AttachmentBinaryISOConverter'
};
